def transform(grid):
 g=[r[:] for r in grid]
 # rotate green cells in each pair of azure rows counterclockwise within edge 2x2 blocks
 for r in range(0,len(grid)-1,4):
  if r+2>=len(grid): break
  w=len(grid[0])
  for side in (0,1):
   cols=(0,1) if side==0 else (w-2,w-1)
   block=[[grid[r+dr][c] for c in cols] for dr in (0,2)]
   # only modify if all non-green cells azure
   if all(x in (3,8) for row in block for x in row):
    rot=[[block[0][1],block[1][1]],[block[0][0],block[1][0]]]
    for i,dr in enumerate((0,2)):
     for j,c in enumerate(cols):g[r+dr][c]=rot[i][j]
 for r in range(len(g)):
  for c in range(len(g[0])):
   if grid[r][c]==7:
    center=c>0 and c+1<len(g[0]) and grid[r][c-1]==7 and grid[r][c+1]==7
    g[r][c]=6 if center else 8
    if center and r>0:g[r-1][c]=6
 return g
